/*
    This shader is an implementation of:
    https://www.cs.cmu.edu/~kmcrane/Projects/MonteCarloGeometryProcessing/paper.pdf (esp. Sec. 6.6)

    Basically, a Helmholtz(-Hodge) decomposition decomposes a vector field (top left)
    into rotation-free (top right), divergence-free (bottom left), and harmonic (bottom right) vector fields.

    More details (on the implementation) can be found in Buffer B.
*/

MAIN {
    vec2 p = iMouse.xy == vec2(0) 
        ? vec2(.9 * (-.5 * cos(.9 * (iTime - 10.)) + .5)) 
        : iMouse.xy/R.xy;

    vec2 uv = fract(2. * U / R.xy) + .5 * (1. - (p.x + p.y));

    if (uv.x + uv.y < 1.)
        o.rg = texelFetch(iChannel1, ivec2(U), 0).rg,
        o.zw = vec2(0, 1);
    else {
        o = texelFetch(iChannel0, ivec2(U), 0).zzzz;

        bvec2 s = lessThan(2. * U, R.xy);

        o.rgb *= s.x
            ? ( s.y ? vec3(.49, .44, .96) : vec3(.44, .96, .68) )
            : ( s.y ? vec3(.96, .49, .44) : vec3(.96, .88, .44) );
    }

    o = pow(o, vec4(.455));
}

#define MAIN void mainImage(out vec4 o, vec2 U)
#define R iResolution

const float PI = intBitsToFloat(0x40490fdb);
const float TAU = intBitsToFloat(0x40c90fdb);
const float INV_TAU = intBitsToFloat(0x3e22f983);

vec4 pack( vec4 o1, vec4 o2 ) {
    return uintBitsToFloat( uvec4 (
        packHalf2x16( o1.xy ),
        packHalf2x16( o1.zw ),
        packHalf2x16( o2.xy ),
        packHalf2x16( o2.zw )
    ));
}

void unpack( vec4 o, inout vec4 o1, inout vec4 o2 ) {    
    uvec4 uo = floatBitsToUint(o);
    o1 += vec4 ( unpackHalf2x16(uo.x), unpackHalf2x16(uo.y) );
    o2 += vec4 ( unpackHalf2x16(uo.z), unpackHalf2x16(uo.w) );
}

void unpack_average( sampler2D sp, vec2 U, vec2 R, inout vec4 o1, inout vec4 o2 ) {
    U = .5 * R.xy * fract(2. * U / R.xy);
    unpack(texelFetch(sp, ivec2(U                      ), 0), o1, o2);
    unpack(texelFetch(sp, ivec2(U + .5 * vec2(R.x, 0  )), 0), o1, o2);
    unpack(texelFetch(sp, ivec2(U + .5 * vec2(0,   R.y)), 0), o1, o2);
    unpack(texelFetch(sp, ivec2(U + .5 * vec2(R.x, R.y)), 0), o1, o2);
    o1 *= .25; o2 *= .25;
}

float jenkins_hash( uint );
vec4 jenkins_hash( uvec4 );
vec4 hash( int, uint, vec2 );
vec4 hash43( vec3 );

float sdBezier( vec2, vec2, vec2, vec2 );

float shape_dist(vec2 p) {
    vec4 d1234 = vec4 (
        sdBezier(p,
            vec2(.02, .04),
            vec2(0., .19),
            vec2(.15, .24)),
        sdBezier(p, 
            vec2(.15, .24),
            vec2(.4, .34),
            vec2(.47, .14)),
        sdBezier(p, 
            vec2(.47, .14),
            vec2(.5, .02),
            vec2(.4, .03)),
        sdBezier(p, 
            vec2(.4, .03),
            vec2(.26, .07),
            vec2(.15, .03))
    ),
    d5678 = vec4 (
        sdBezier(p, 
            vec2(.15, .03),
            vec2(.04, -.01),
            vec2(.02, .04)),
        sdBezier(p,     // inner
            vec2(.38, .11),
            vec2(.4, .17),
            vec2(.35, .18)),
        sdBezier(p,
            vec2(.35, .18),
            vec2(.27, .19),
            vec2(.3, .13)),
        sdBezier(p,
            vec2(.3, .13),
            vec2(.35, .06),
            vec2(.38, .11))
    );

    d1234 = mix( d1234, d5678, vec4( greaterThan(abs(d1234), abs(d5678)) ) );

    d1234.xy = mix( d1234.xy, d1234.zw, vec2( greaterThan(abs(d1234.xy), abs(d1234.zw)) ) );

    return abs(d1234.x) < abs(d1234.y) ? d1234.x : d1234.y;
}

// from https://www.shadertoy.com/view/MlKcDD

float dot2( vec2 v ) { return dot(v,v); }
float cro( vec2 a, vec2 b ) { return a.x*b.y-a.y*b.x; }
float cos_acos_3( float x ) { x=sqrt(0.5+0.5*x); return x*(x*(x*(x*-0.008972+0.039071)-0.107074)+0.576975)+0.5; } // https://www.shadertoy.com/view/WltSD7

float sdBezier( in vec2 pos, in vec2 A, in vec2 B, in vec2 C )
{    
    vec2 a = B - A;
    vec2 b = A - 2.0*B + C;
    vec2 c = a * 2.0;
    vec2 d = A - pos;

    // cubic to be solved (kx*=3 and ky*=3)
    float kk = 1.0/dot(b,b);
    float kx = kk * dot(a,b);
    float ky = kk * (2.0*dot(a,a)+dot(d,b))/3.0;
    float kz = kk * dot(d,a);      

    float res = 0.0;
    float sgn = 0.0;

    float p  = ky - kx*kx;
    float q  = kx*(2.0*kx*kx - 3.0*ky) + kz;
    float p3 = p*p*p;
    float q2 = q*q;
    float h  = q2 + 4.0*p3;


    if( h>=0.0 ) 
    {   // 1 root
        h = sqrt(h);
        vec2 x = (vec2(h,-h)-q)/2.0;

        vec2 uv = sign(x)*pow(abs(x), vec2(1.0/3.0));
        float t = uv.x + uv.y;

		// from NinjaKoala - single newton iteration to account for cancellation
        t -= (t*(t*t+3.0*p)+q)/(3.0*t*t+3.0*p);

        t = clamp( t-kx, 0.0, 1.0 );
        vec2  w = d+(c+b*t)*t;
        res = dot2(w);
    	sgn = cro(c+2.0*b*t,w);
    }
    else 
    {   // 3 roots
        float z = sqrt(-p);

        float v = acos(q/(p*z*2.0))/3.0;
        float m = cos(v);
        float n = sin(v);

        n *= sqrt(3.0);
        vec3  t = clamp( vec3(m+m,-n-m,n-m)*z-kx, 0.0, 1.0 );
        vec2  qx=d+(c+b*t.x)*t.x; float dx=dot2(qx), sx=cro(a+b*t.x,qx);
        vec2  qy=d+(c+b*t.y)*t.y; float dy=dot2(qy), sy=cro(a+b*t.y,qy);
        if( dx<dy ) {res=dx;sgn=sx;} else {res=dy;sgn=sy;}
    }

    return sqrt( res )*sign(sgn);
}

// from https://www.shadertoy.com/view/Msf3WH
vec2 hash( vec2 p ) { // replace this by something better
	p = vec2( dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)) );
	return -1.0 + 2.0*fract(sin(p)*43758.5453123);
}

float noise( vec2 p ) {
    const float K1 = 0.366025404; // (sqrt(3)-1)/2;
    const float K2 = 0.211324865; // (3-sqrt(3))/6;

	vec2  i = floor( p + (p.x+p.y)*K1 );
    vec2  a = p - i + (i.x+i.y)*K2;
    float m = step(a.y,a.x); 
    vec2  o = vec2(m,1.0-m);
    vec2  b = a - o + K2;
	vec2  c = a - 1.0 + 2.0*K2;
    vec3  h = max( 0.5-vec3(dot(a,a), dot(b,b), dot(c,c) ), 0.0 );
	vec3  n = h*h*h*h*vec3( dot(a,hash(i+0.0)), dot(b,hash(i+o)), dot(c,hash(i+1.0)));
    return dot( n, vec3(70.0) );
}

// from https://www.shadertoy.com/view/4djSRW

vec4 hash43(vec3 p){
    vec4 p4 = fract(vec4(p.xyzx) * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+19.19);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}

//

float jenkins_hash(uint a) {
    a -= (a<<6);
    a ^= (a>>17);
    a -= (a<<9);
    a ^= (a<<4);
    a -= (a<<3);
    a ^= (a<<10);
    a ^= (a>>15);
    return float(a) / 4294967296.;
}

vec4 jenkins_hash(uvec4 a) {
    a -= (a<<6);
    a ^= (a>>17);
    a -= (a<<9);
    a ^= (a<<4);
    a -= (a<<3);
    a ^= (a<<10);
    a ^= (a>>15);
    return vec4(a) / 4294967296.;
}

// this hash...
vec4 hash(int a, uint b, vec2 c) {
    uint seed = uint((a << 4) + 0xf13) ^ (floatBitsToUint(c.x)) + (b + 0x15u) ^ floatBitsToUint(c.y);
    return jenkins_hash(uvec4(seed++, seed <<= 4, seed--, seed));
}

/*
    precompute the input vector field (X), 
    its divergence and curl
    only on the first frame,

    layout: { X.x, X.y, div X, curl X }
*/

vec2 sample_X(vec2 p) {
    return .4 * normalize(vec2( noise(5.*p), noise(5.*p + 100.) ));
}

const float EPS = 1e-3,
            HALF_INV_EPS = .5 / EPS;
const vec2 dx = vec2(EPS, 0),
           dy = vec2(0, EPS);

MAIN {
    if (iFrame != 0) {
        o = texelFetch(iChannel0, ivec2(U), 0); 
        return;
    }

    vec2 uv = U/R.x;

    U *= 2.;
    if (U.x > R.x || U.y < R.y) { o = vec4(0); return; }

    vec2 dXdx = HALF_INV_EPS * ( sample_X(uv + dx) - sample_X(uv - dx) ),
         dXdy = HALF_INV_EPS * ( sample_X(uv + dy) - sample_X(uv - dy) );

    o = vec4 (
        sample_X(uv),       // X
        dXdx.x + dXdy.y,    // div X
        dXdx.y - dXdy.x     // curl X (yes, it does seem like the curl is scalar)
    );

    o.zw = -o.zw; // without, the gradients would be inverted, for some reason
}

/*  
    This buffer handles the actual WoS estimation.

    As described in the aforementioned paper, the desired decomposition requires the solution to two (Poisson) equations,
    only differing by their source term f, sampled from Buffer A.

    Because the computations for the random walk are the same for both estimators (i.e., they can simply take the same path),
    both PDEs can be solved simultaneously, with little extra cost.
    Each estimator has to store 4 floating point values (the running estimates of
    the scalar potential u (or a), its gradient ∇u (or ∇a), and the source f = ∇⋅X (or ∇xX)).
    Hence, each pixel stores 8 half-precision floats, arranged like so (channels are separated by a comma):

    { ∇u, u ∇⋅X, ∇a, a ∇xX }

    Each corner computes one sample of the estimators (the vector fields are displayed at quarter resolution anyway).
    So in total, 8 samples are computed every frame!

    Below, you can find a version without this optimization for a single estimator.
*/

const float EPSILON = 0.001;
const float HALF_INV_EPSILON = .5 / EPSILON;

const uint MAX_STEPS = 24u;

MAIN {
    o = vec4(0);

    vec2 uv = U / R.xy;

    vec2 x = vec2(.5, .5 * R.y / R.x) * fract(2. * U/R.xy);

    if (shape_dist(x) < 0.) discard;

    vec4 o1 = vec4(0), o2 = vec4(0);

    if (iFrame!=0) {
        unpack_average(iChannel1, U, R.xy, o1, o2);
    }

    vec2 u = vec2(0), u_grad_corr;
    vec4 grad = vec4(0); vec2 initial_grad;

    vec2 f_x_0;

    float d = shape_dist(x);

    for (uint i = 0u; d > EPSILON; ++i) {
        if (i >= MAX_STEPS) { 
            float k = float(iFrame) / float(iFrame + 1);
            o1.xyz *= k; o2.xyz *= k;
            o = pack(o1, o2); 
            return; 
        }

        float d2 = d * d;

        float rand1 = TAU * jenkins_hash( uint(iFrame << 5) + i + floatBitsToUint(d) );

        vec2 v_x_1 = vec2(cos(rand1), sin(rand1));
        vec2 new_x = x + d * v_x_1;

        // sample two y uniform on ball of radius d (y = (y1.xy, y2.xy))
        // as described in 
        // Peter Shirley. Discrepancy as a quality measure for sample distributions. Euro-graphics ’91 Proceedings, pages 183–193, June 1991
        // note: I do not know whether reusing the same, single y would be possible or introduce bias
        vec4 rand = hash(iFrame, i, uv);
        rand = 2. * rand - 1.;
        vec2 phi = rand.xy / rand.zw;
        vec2 r = d * abs(rand.zw) + 1e-4;
        vec4 y = x.xxyy + d * rand.zwzw * vec4(cos(phi), sin(phi));

        // |B(x)| f(y) G(x,y) (Eqn. 8)
        // note: the pi from |B| and G cancel
        // note: You could apply importance sampling on G, but inverse transform 
        //       sampling is not possible in 2D for there exists  no  analytical 
        //       cdf (I reckon it would work in 3D, though).
        //       I did not try other importance sampling techniques.
        u += d2 * .5 * log(d / r.x) 
           * texture(iChannel0, y.xz * vec2(1, R.x / R.y) + vec2(0, .5)).zw;


        // gradient and control variate (Sec. 3.1, 4.1 resp.)
        // Eqn. 14
        if (i == 0u) {
            // Eqn. 16
            u_grad_corr = vec2( dot(o1.xy, d * v_x_1), dot(o2.xy, d * v_x_1));

            // Eqn. 13
            initial_grad = 2. / d * v_x_1;

            f_x_0 = texture(iChannel0, y.yw * vec2(1, R.x / R.y) + vec2(0, .5)).zw;

            grad += d2 * PI * (f_x_0 - vec2(o1.w, o2.w)).xxyy
              * ((y.yw - x) * INV_TAU * ( 1. / (r.y * r.y) - 1. / d2 )).xyxy;
        }

        x = new_x;
        d = shape_dist(x);
    }

    // Eqn. 13
    grad += initial_grad.xyxy * vec4(u - o1.z, u - o2.z);

    // Eqn. 16
    u -= u_grad_corr;

    // average samples
    float inv_num_samples = 1. / float(iFrame + 1);
    o1 = (o1 * float(iFrame) + vec4(grad.xy, u.x, f_x_0.x)) * inv_num_samples;
    o2 = (o2 * float(iFrame) + vec4(grad.zw, u.y, f_x_0.y)) * inv_num_samples;

    o = pack(o1, o2);
}

// WoS estimator for a single equation
// source is vec4(0,0,1,0) for divX; vec4(0,0,0,1) for curlX
/*void wos_poisson_estimator(out vec4 o, vec2 U, vec4 source, vec2 x) {
