}*/

MAIN {    
    o = vec4(0);

    vec2 uv = U / R.xy;

    vec2 x = vec2(.5, .5 * R.y / R.x) * fract(2. * U/R.xy);

    if (shape_dist(x) < 0.) discard;

    // input (X)
    if (uv.x < .5 && uv.y > .5)
        o = texelFetch(iChannel0, ivec2(U), 0);

    // harmonic (Y = X - ∇u - J∇a)
    else if (uv.x > .5 && uv.y < .5)
        o.xy = texture(iChannel2, uv + vec2(-.5, .5)).xy
             - texture(iChannel2, uv + vec2(0., .5)).xy
             - texture(iChannel2, uv + vec2(-.5, 0.)).xy;

    // average the four estimates from buffer B
    else {
        vec4 o1 = vec4(0), o2 = vec4(0);

        if (2. * U.x > R.x) U -= .5 * R.xy;

        unpack_average(iChannel1, U, R.xy, o1, o2);

        o = uv.x > .5 ? o1 : vec4(-1,1,0,0) * o2.yxzw;

        o.zw = vec2(0);
    }
}

// particle simulation
// thanks to this amazing shader: https://www.shadertoy.com/view/MdGBWG (adapted)

MAIN {
    o = vec4(0);

    if (shape_dist(vec2(.5, .5 * R.y / R.x) * fract(2. * U/R.xy)) < 0.) return;

    ivec2 iU = ivec2(U);

    o.z = exp(-3. * iTimeDelta) * texelFetch(iChannel0, iU, 0).z;
    o.xy = vec2(0);

    for (int i = -1; i <= 1; ++i)
        for (int j = -1; j <= 1; ++j) {
            ivec2 P = iU + ivec2(i, j);
            vec2 vP = vec2(P);
            vec2 p = texelFetch(iChannel0, P, 0).xy;

            vec4 rand = hash43(vec3(vP, float(iFrame)));

            if (p == vec2(0)) {
                if (rand.x > 1e-4) continue;
                p = vP + rand.yz; // add particle
            } else if (rand.w < 8e-3)
                continue; // remove particle

            p += texelFetch(iChannel1, P, 0).xy;

            if (iU == ivec2(p)) {
                o.xyz = vec3(p.xy, 1);
                return;
            }
        }
}
